#include <stdio.h>
int main(void) {
    int value = 20;
    int *outer = &value;
    printf("outer=%d\n", value);
    {
        int value = 40;
        printf("inner=%d distinct=%d\n", value, outer != &value);
    }
    printf("after=%d\n", value);
    while (value++ < 22) {
        int value = 80;
        value++;
        printf("loop=%d\n", value);
    }
    printf("final=%d\n", value);
    return 0;
}

