#include <stdio.h>
#include "batch_api.h"
int batch_count = 0;
int main(void) {
    int value = 0;
    register int item;
    while (scanf("%d", &value) == 1 && value > 0 && value <= 5) {
        batch_count++;
        for (item = value; item >= 0; item--) batch_add(item);
    }
    printf("batches=%d\n", batch_count);
    return 0;
}

