#define DICE_CORE_API_H
extern unsigned int dice_core_calls;
int dice_core_many(int dice, int sides);
#endif

#include <stdlib.h>
#include "dice_core_api.h"
unsigned int dice_core_calls = 0u;
static int one_die(int sides) {
    dice_core_calls++;
    return rand() % sides + 1;
}
int dice_core_many(int dice, int sides) {
    if (dice < 1 || dice > 8 || sides < 2 || sides > 20) return -1;
    int sum = 0;
    for (int i = 0; i < dice; i++) sum += one_die(sides);
    return sum;
}

